import pandas as pd

def total_time_spent_by_each_employee(employees: pd.DataFrame) -> pd.DataFrame:
    employees["total_time"] = employees["out_time"] - employees["in_time"]
    res = employees.groupby(["event_day", "emp_id"], as_index=False)["total_time"].sum()
    return res.rename(columns={"event_day": "day"})
